# Surah Al-Baqarah (chapter 2) — part 22: ayat 211-220 (IDs 218-227)
SURAH = 2

ENTRIES = {
218: (
"بنی اسرائیل سے سوال کرو کہ ہم نے انہیں کتنی واضح نشانیاں دیں — اور جو کوئی اللہ کی نعمت کو بدل دے اس کے آنے کے بعد تو بے شک اللہ سخت عذاب والا ہے۔",
"""۱۔ بنی اسرائیل کو یاد دلایا جا رہا ہے کہ اللہ نے انہیں کتنے واضح معجزات دیے۔
۲۔ ’’سَلْ بَنِي إِسْرَائِيلَ كَمْ آتَيْنَاهُم مِّنْ آيَۃٍ بَيِّنَۃٍ‘‘ — بنی اسرائیل سے سوال کرو کہ ہم نے انہیں کتنی واضح نشانیاں دیں — یعنی یدِ بیضاء، عصا، پھٹتا سمندر، ابر کا سایہ — سب واضح عجائبات۔
۳۔ ’’وَمَن يُبَدِّلْ نِعْمَۃَ اللّٰہِ مِن بَعْدِ مَا جَاءَتْهُ فَإِنَّ اللّٰہَ شَدِيدُ الْعِقَابِ‘‘ — اور جو کوئی اللہ کی نعمت کو بدل دے اس کے آنے کے بعد تو بے شک اللہ سخت عذاب والا ہے — یعنی نعمت کی ناشکری کا انجام سخت عذاب ہے۔
۴۔ عملی سبق: اللہ کی نعمتوں کی ناشکری نہ کرو؛ نعمت کے بدلنے والوں کو اللہ سخت عذاب دیتا ہے۔"""
),
219: (
"کافروں کے لیے دنیاوی زندگی سجائی گئی ہے اور وہ ایمان والوں کا مذاق اڑاتے ہیں — اور جو تقویٰ اختیار کریں گے وہ قیامت کے دن ان پر فوقیت رکھیں گے — اور اللہ جسے چاہے بے حساب رزق دیتا ہے۔",
"""۱۔ کافروں کی دنیاوی شان اور مؤمنوں کی آخرت کی برتری بیان ہو رہی ہے۔
۲۔ ’’زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا‘‘ — کافروں کے لیے دنیاوی زندگی سجائی گئی ہے — یعنی دنیاوی سازوسامان ان کی آنکھوں میں خوش نما ہے، آخرت کی فکر نہیں۔
۳۔ ’’وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا‘‘ — اور وہ ایمان والوں کا مذاق اڑاتے ہیں — یعنی مؤمنوں کی سادہ زندگی پر طعنہ۔
۴۔ ’’وَالَّذِينَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيَامَۃِ‘‘ — اور جو تقویٰ اختیار کریں گے وہ قیامت کے دن ان پر فوقیت رکھیں گے — یعنی قیامت میں متقی بلند مقام پائیں گے۔
۵۔ ’’وَاللّٰہُ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ‘‘ — اور اللہ جسے چاہے بے حساب رزق دیتا ہے — یعنی رزق کا نظام مکمل طور پر اللہ کے ہاتھ میں ہے۔
۶۔ عملی سبق: دنیا کی آسائشوں کے دھوکے میں مت آؤ؛ تقویٰ ہی اصل کامیابی کی کلید ہے۔"""
),
220: (
"لوگ ایک امت تھے — پھر اللہ نے نبی (پیغمبر) بھیجے خوشخبری دینے والے اور ڈرانے والے — اور ان کے ساتھ حق کے ساتھ کتاب نازل کی تاکہ ان کے درمیان فیصلہ کرے اس میں جس میں وہ اختلاف کرتے تھے — اور اس میں اختلاف نہیں کیا مگر انہی لوگوں نے جنہیں وہ دی گئی اس کے بعد واضح دلائل آ چکے — آپس کے ظلم کی وجہ سے — پس اللہ نے ہدایت دی ایمان والوں کو اس حق کی جو وہ اختلاف کرتے تھے — اپنے حکم سے — اور اللہ جسے چاہے سیدھے راستے کی ہدایت دیتا ہے۔",
"""۱۔ انسانیت کی تاریخ کا نقشہ — ایک امت سے اختلاف اور نبیوں کی آمد۔
۲۔ ’’كَانَ النَّاسُ أُمَّۃً وَاحِدَۃً‘‘ — لوگ ایک امت تھے — یعنی ابتدائی انسان ایک نیچر اور مذہب پر تھے۔
۳۔ ’’فَبَعَثَ اللّٰہُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنذِرِينَ‘‘ — پھر اللہ نے نبی (پیغمبر) بھیجے خوشخبری دینے والے اور ڈرانے والے — یعنی ہر دور میں انبیاء آتے رہے۔
۴۔ ’’وَأَنزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ فِيمَا اخْتَلَفُوا فِيهِ‘‘ — اور ان کے ساتھ حق کے ساتھ کتاب نازل کی تاکہ ان کے درمیان فیصلہ کرے اس میں جس میں وہ اختلاف کرتے تھے — یعنی کتاب ہی تمام اختلافات کا حتمی فیصلہ ہے۔
۵۔ ’’وَمَا اخْتَلَفَ فِيهِ إِلَّا الَّذِينَ أُوتُوهُ مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ‘‘ — اور اس میں اختلاف نہیں کیا مگر انہی لوگوں نے جنہیں وہ دی گئی اس کے بعد واضح دلائل آ چکے — آپس کے ظلم کی وجہ سے — یعنی اہل کتاب نے بھی دلائل جاننے کے باوجود تعصب سے اختلاف کیا۔
۶۔ ’’فَهَدَى اللّٰہُ الَّذِينَ آمَنُوا لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِّ بِإِذْنِهِ‘‘ — پس اللہ نے ہدایت دی ایمان والوں کو اس حق کی جو وہ اختلاف کرتے تھے — اپنے حکم سے — یعنی مومنوں کو اللہ نے درست راہ دکھائی۔
۷۔ ’’وَاللّٰہُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ‘‘ — اور اللہ جسے چاہے سیدھے راستے کی ہدایت دیتا ہے۔
۸۔ عملی سبق: اختلافات میں قرآن و سنت پر رجوع کرو؛ تعصب کو چھوڑ کر حق کی تلاش بڑھو۔"""
),
221: (
"کیا تم سمجھتے ہو کہ تم جنت میں داخل ہو جاؤ گے حالانکہ تمہارے سامنے ابھی تک وہ حالت نہیں آئی جو تم سے پہلے والوں پر آئی؟ — ان پر تنگی اور تکلیف پہنچی اور وہ جھنجھوڑے گئے یہاں تک کہ رسول اور اس کے ساتھ والے ایمان والے کہتے تھے کہ اللہ کی مدد کب آئے گی؟ — جان لو کہ اللہ کی مدد قریب ہے۔",
"""۱۔ ایمان کی آزمائشوں کا ذکر — کسی کو بھی جنت مفت نہیں ملتی۔
۲۔ ’’أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّۃَ وَلَمَّا يَأْتِكُم مَّثَلُ الَّذِينَ خَلَوْا مِن قَبْلِكُمْ‘‘ — کیا تم سمجھتے ہو کہ تم جنت میں داخل ہو جاؤ گے حالانکہ تمہارے سامنے ابھی تک وہ حالت نہیں آئی جو تم سے پہلے والوں پر آئی — یعنی پہلی امتوں کی آزمائشیں ہمارے سامنے ہیں۔
۳۔ ’’مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا‘‘ — ان پر تنگی اور تکلیف پہنچی اور وہ جھنجھوڑے گئے — یعنی مشکلات نے ان کا ایمان توڑا نہیں بلکہ استوار کیا۔
۴۔ ’’حَتَّىٰ يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَىٰ نَصْرُ اللّٰہِ‘‘ — یہاں تک کہ رسول اور اس کے ساتھ والے ایمان والے کہتے تھے کہ اللہ کی مدد کب آئے گی؟ — یعنی یہاں تک کہ ہر ایک مایوس نظر آنے لگے — مگر مدد قریب تھی۔
۵۔ ’’أَلَا إِنَّ نَصْرَ اللّٰہِ قَرِيبٌ‘‘ — جان لو کہ اللہ کی مدد قریب ہے — یعنی اللہ کی مدد ہمیشہ قریب ہوتی ہے۔
۶۔ عملی سبق: مشکل حالات میں مایوس نہ ہو؛ اللہ کی مدد قریب ہوتی ہے — بس ثابت قدمی سے ڈٹے رہو۔"""
),
222: (
"آپ سے پوچھا جاتا ہے کہ کیا خرچ کریں؟ — کہہ دیجیے: جو بھلائی خرچ کرو وہ والدین، قریبی رشتہ داروں، یتیموں، مسکینوں اور مسافروں کے لیے ہے — اور تم جو بھی بھلائی کرو بے شک اللہ اسے جانتا ہے۔",
"""۱۔ خرچ کا حکم — صدقہ اور زکوٰۃ کے مستحقین کی تفصیل۔
۲۔ ’’يَسْأَلُونَكَ مَاذَا يُنفِقُونَ‘‘ — آپ سے پوچھا جاتا ہے کہ کیا خرچ کریں؟ — یعنی صدقہ کی نوعیت اور مقدار کی تعیین۔
۳۔ ’’قُلْ مَا أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالْأَقْرَبِينَ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ‘‘ — کہہ دیجیے: جو بھلائی خرچ کرو وہ والدین، قریبی رشتہ داروں، یتیموں، مسکینوں اور مسافروں کے لیے ہے — یعنی ان پانچ طبقوں پر خرچ کرو۔
۴۔ ’’وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللّٰہَ بِهِ عَلِيمٌ‘‘ — اور تم جو بھی بھلائی کرو بے شک اللہ اسے جانتا ہے — یعنی ہر نیکی اللہ کے علم میں ہے۔
۵۔ عملی سبق: اپنے قریبی رشتہ داروں سے شروع کر کے ہر حاجت مند کی مدد کرو؛ خرچ کے معیار کو اپنے گھر سے بڑھاؤ۔"""
),
223: (
"تم پر قتال (جنگ) فرض کیا گیا ہے حالانکہ وہ تمہارے لیے ناپسند ہے — اور ہو سکتا ہے کہ تم کوئی چیز ناپسند کرو حالانکہ وہ تمہارے لیے بہتر ہو — اور ہو سکتا ہے کہ تم کوئی چیز پسند کرو حالانکہ وہ تمہارے لیے بُری ہو — اور اللہ جانتا ہے اور تم نہیں جانتے۔",
"""۱۔ قتال (دفاعی جنگ) کا حکم — لیکن یہ بھی بیان کہ لوگ اسے ناپسند کرتے ہیں مگر اللہ کے فیصلے میں خیر ہے۔
۲۔ ’’كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ‘‘ — تم پر قتال (جنگ) فرض کیا گیا ہے حالانکہ وہ تمہارے لیے ناپسند ہے — یعنی لڑائی فطری طور پر مشکل ہے مگر شریعت کی ذمہ داری ہے۔
۳۔ ’’وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ‘‘ — اور ہو سکتا ہے کہ تم کوئی چیز ناپسند کرو حالانکہ وہ تمہارے لیے بہتر ہو — یعنی بظاہر مشکل مگر نتیجہ بہتر۔
۴۔ ’’وَعَسَىٰ أَن تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَّكُمْ‘‘ — اور ہو سکتا ہے کہ تم کوئی چیز پسند کرو حالانکہ وہ تمہارے لیے بُری ہو — یعنی بظاہر خوشیاں مگر آخیر نقصان۔
۵۔ ’’وَاللّٰہُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ‘‘ — اور اللہ جانتا ہے اور تم نہیں جانتے — یعنی اللہ کا علم سب سے کامل ہے۔
۶۔ عملی سبق: اللہ کے احکامات کو آسان سمجھو؛ کبھی کبھی ناپسند چیز بھی تمہارے لیے خیر ہوتی ہے۔"""
),
224: (
"آپ سے پوچھا جاتا ہے حرمت والے مہینے (کے بارے) میں اس میں لڑائی کا — کہہ دیجیے: اس میں لڑائی بڑا گناہ ہے — اور اللہ کی راہ سے روکنا اور اس کا کفر کرنا اور مسجد حرام اور اس کے باشندوں کو اس سے نکالنا اللہ کے نزدیک بڑے (گناہ) ہیں — اور فتنہ قتل سے بھی بڑا ہے — اور وہ ہمیشہ تم سے جنگ کرتے رہیں گے یہاں تک کہ (اگر ممکن ہو) تمہیں تمہارے دین سے پھیر دیں — اور جو کوئی تم میں سے اپنے دین سے پھر جائے اور کافر ہو کر مرے تو ان کے اعمال دنیا اور آخرت میں ضائع ہو گئے — اور یہی جہنم والے ہیں — وہ اس میں ہمیشہ رہیں گے۔",
"""۱۔ حرمت والے مہینے (رجب، ذوالقعدہ، ذوالحجہ، محرم) میں لڑائی کا حکم اور اس کی سختی۔
۲۔ ’’يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ‘‘ — آپ سے پوچھا جاتا ہے حرمت والے مہینے (کے بارے) میں اس میں لڑائی کا — کہہ دیجیے: اس میں لڑائی بڑا گناہ ہے — یعنی ان مہینوں میں لڑائی جائز نہیں۔
۳۔ ’’وَصَدٌّ عَن سَبِيلِ اللّٰہِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِندَ اللّٰہِ‘‘ — اور اللہ کی راہ سے روکنا اور اس کا کفر کرنا اور مسجد حرام اور اس کے باشندوں کو اس سے نکالنا اللہ کے نزدیک بڑے (گناہ) ہیں — یعنی مکہ سے نکالے جانا بدتر ظلم ہے۔
۴۔ ’’وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ‘‘ — اور فتنہ قتل سے بھی بڑا ہے — یعنی دین سے روکنا قتل سے بھی بدتر ہے۔
۵۔ ’’وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ اسْتَطَاعُوا‘‘ — اور وہ ہمیشہ تم سے جنگ کرتے رہیں گے یہاں تک کہ (اگر ممکن ہو) تمہیں تمہارے دین سے پھیر دیں — یعنی کفار کا مسلسل مقصد انہیں دین سے ہٹانا ہے۔
۶۔ ’’وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَۃِ‘‘ — اور جو کوئی تم میں سے اپنے دین سے پھر جائے اور کافر ہو کر مرے تو ان کے اعمال دنیا اور آخرت میں ضائع ہو گئے — یعنی ارتداد کا انجام دنیا اور آخرت دونوں میں نقصان۔
۷۔ ’’وَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ‘‘ — اور یہی جہنم والے ہیں — وہ اس میں ہمیشہ رہیں گے۔
۸۔ عملی سبق: دین پر ثابت قدم رہو؛ دنیاوی مفاد کے لیے دین سے سمجھوتہ نہ کرو — نقصان دونوں جہانوں میں ہے۔"""
),
225: (
"بے شک جو لوگ ایمان لائے اور جنہوں نے ہجرت کی اور اللہ کی راہ میں جہاد کیا — یہی وہ ہیں جو اللہ کی رحمت کی امید رکھتے ہیں — اور اللہ بخشنے والا، نہایت رحم والا ہے۔",
"""۱۔ ہجرت اور جہاد کرنے والوں کا انعام بیان ہو رہا ہے — اللہ کی رحمت کی امید۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللّٰہِ‘‘ — بے شک جو لوگ ایمان لائے اور جنہوں نے ہجرت کی اور اللہ کی راہ میں جہاد کیا — یعنی تین صفات: ایمان، ہجرت، جہاد۔
۳۔ ’’أُولَٰئِكَ يَرْجُونَ رَحْمَۃَ اللّٰہِ‘‘ — یہی وہ ہیں جو اللہ کی رحمت کی امید رکھتے ہیں — یعنی انہیں اللہ کی رحمت کا یقین ہے۔
۴۔ ’’وَاللّٰہُ غَفُورٌ رَّحِيمٌ‘‘ — اور اللہ بخشنے والا، نہایت رحم والا ہے۔
۵۔ عملی سبق: دین کے لیے اپنی قربانیاں دینے سے گریز نہ کرو؛ اللہ کی رحمت ہر قربانی کا بدلہ ہے۔"""
),
226: (
"آپ سے شراب اور جوئے کے بارے میں پوچھا جاتا ہے — کہہ دیجیے: ان دونوں میں بڑا گناہ ہے اور لوگوں کے لیے کچھ فائدے ہیں — اور ان کا گناہ ان کے فائدوں سے بڑا ہے — اور وہ آپ سے پوچھتے ہیں کہ کیا خرچ کریں؟ — کہہ دیجیے: معاف (زیادہ) خرچ کرو — اسی طرح اللہ تمہارے لیے آیات بیان کرتا ہے — شاید کہ تم غور و فکر کرو۔",
"""۱۔ شراب اور جوئے پر پہلی (اور بعد میں آخری) تحریم آیت — تدریجی احکام۔
۲۔ ’’يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ‘‘ — آپ سے شراب اور جوئے کے بارے میں پوچھا جاتا ہے — شراب = نشہ آور شراب؛ میسر = جوا/قمار۔
۳۔ ’’قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ‘‘ — کہہ دیجیے: ان دونوں میں بڑا گناہ ہے اور لوگوں کے لیے کچھ فائدے ہیں — یعنی کاروباری اور وقتی فائدہ ہے مگر بنیادی نقصان زیادہ۔
۴۔ ’’وَإِثْمُهُمَا أَكْبَرُ مِن نَّفْعِهِمَا‘‘ — اور ان کا گناہ ان کے فائدوں سے بڑا ہے — یعنی خرابی زیادہ، فائدہ کم۔
۵۔ ’’وَيَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلِ الْعَفْوَ‘‘ — اور وہ آپ سے پوچھتے ہیں کہ کیا خرچ کریں؟ — کہہ دیجیے: معاف (زیادہ) خرچ کرو — یعنی اپنی ضرورت سے زائد مال خرچ کرو۔
۶۔ ’’كَذَٰلِكَ يُبَيِّنُ اللّٰہُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ‘‘ — اسی طرح اللہ تمہارے لیے آیات بیان کرتا ہے — شاید کہ تم غور و فکر کرو۔
۷۔ عملی سبق: شراب اور جوئے سے دور رہو؛ اپنا مال اللہ کی راہ میں خرچ کرو — حلال اور طیب کمائی ہی برکت ہے۔"""
),
227: (
"دنیا اور آخرت میں (یہی حکم ہے) — اور وہ آپ سے یتیموں کے بارے میں پوچھتے ہیں — کہہ دیجیے: ان کی اصلاح بہتر ہے — اور اگر تم ان کے ساتھ مل رہو (ان کے مال میں) تو وہ تمہارے بھائی ہیں — اور اللہ تباہ کن سے مصلح کو جانتا ہے — اور اگر اللہ چاہتا تو تمہیں تکلیف میں ڈال دیتا — بے شک اللہ عزت والا، حکمت والا ہے۔",
"""۱۔ یتیموں کے ساتھ سلوک کا اصول بیان ہو رہا ہے — ان کا مال امانت ہے۔
۲۔ ’’يَسْأَلُونَكَ عَنِ الْيَتَامَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ‘‘ — اور وہ آپ سے یتیموں کے بارے میں پوچھتے ہیں — کہہ دیجیے: ان کی اصلاح بہتر ہے — یعنی یتیم کی پرورش اور اس کے مال کی حفاظت ذمہ داری ہے۔
۳۔ ’’وَإِن تُخَالِطُوهُمْ فَإِخْوَانُكُمْ‘‘ — اور اگر تم ان کے ساتھ مل رہو (ان کے مال میں) تو وہ تمہارے بھائی ہیں — یعنی اگر یتیم کے ساتھ مال میں مل جاؤ تو اسے بھائی سمجھ کر معاملہ کرو۔
۴۔ ’’وَاللّٰہُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ‘‘ — اور اللہ تباہ کن سے مصلح کو جانتا ہے — یعنی جو یتیم کے مال کو کھاتا ہے وہ بدتر ہے۔
۵۔ ’’وَلَوْ شَاءَ اللّٰہُ لَأَعْنَتَكُمْ‘‘ — اور اگر اللہ چاہتا تو تمہیں تکلیف میں ڈال دیتا — یعنی اللہ ہر معاملے میں آسانی چاہتا ہے — ایک دوسرے کے ساتھ معاملہ میں نرمی۔
۶۔ ’’إِنَّ اللّٰہَ عَزِيزٌ حَكِيمٌ‘‘ — بے شک اللہ عزت والا، حکمت والا ہے۔
۷۔ عملی سبق: یتیموں اور غریبوں کا خیال رکھو؛ ان کے مال کو اپنے مال کی طرح سمجھو — یہی ایمان کی تکمیل ہے۔"""
),
}
